// Orca's Tab::select_preset asks what to do with the outgoing preset's unsaved
// edits ("Transfer or discard changes"). JusPrin never asks a person to save
// or discard: the project is saved to its version history, which keeps the
// edits, and they are dropped as Orca's Discard would. Without the shell's
// save step, or when that save fails, they stay and Orca asks, so nothing is
// lost.
void drop_edits_kept_in_history(Tab& tab, const std::string& next_preset)
{
    PresetCollection& presets = *tab.get_presets();
    if (presets.get_edited_preset().name == next_preset || !presets.current_is_dirty())
        return;
    if (!history_save_step() || !history_save_step()())
        return;
    presets.discard_current_changes();
    tab.load_current_preset();
}

